/* CAPE Digital Media Unit 1 Glossary — Developed by Kester Small */
window.COURSE_GLOSSARY={"cats":{"M1":"Understanding Digital Media","M2":"The Digital Media Ecosystem","M3":"Creative Solution Design"},"refs":{},"terms":[{"t":"180-degree rule","s":"C","m":["3"],"c":"M3","d":["The continuity rule that keeps all cameras on one side of a line of action between characters, so they keep their screen positions."],"r":[]},{"t":"4Ps of marketing","s":"C","m":["2"],"c":"M2","d":["Product, Price, Place and Promotion: the marketing mix used to plan how a product reaches and persuades its market."],"r":[]},{"t":"60-30-10 rule","s":"C","m":["3"],"c":"M3","d":["A palette guide: about 60% dominant colour, 30% secondary colour and 10% accent."],"r":[]},{"t":"Accelerator / incubator","s":"C","m":["2"],"c":"M2","d":["Programmes that support start-ups: incubators nurture early ideas over a longer period; accelerators run short, intensive programmes, often with seed funding."],"r":[]},{"t":"Acceptance","s":"C","m":["3"],"c":"M3","d":["The first stage of the creative design process: recognising and committing to the problem or brief, including its constraints, as your responsibility."],"r":[]},{"t":"Accessibility","s":"G","m":["3","1"],"c":"M3","d":["Design practice ensuring digital content is usable by people with diverse abilities and needs.","Designing content so that people with disabilities can use it, e.g. captions, transcripts, alt text, readable fonts and sufficient colour contrast."],"r":[]},{"t":"Accessibility tools","s":"G","m":["1"],"c":"M1","d":["Tools specifically supporting users with disabilities to access and interact with digital content."],"r":[]},{"t":"Active negative space","s":"C","m":["3"],"c":"M3","d":["Empty space deliberately shaped to carry meaning, such as a hidden symbol in a logo; passive negative space is margins and padding."],"r":[]},{"t":"Additive colour (RGB)","s":"C","m":["3"],"c":"M3","d":["Colour made by adding red, green and blue light, as on screens. No light gives black; all three at full strength give white."],"r":[]},{"t":"Advertiser","s":"C","m":["2"],"c":"M2","d":["A brand or agency that pays for audience attention through targeted digital advertising, funding much of the ecosystem."],"r":[]},{"t":"Affective computing","s":"C","m":["1"],"c":"M1","d":["Technology that detects, interprets and responds to human emotions; also called emotion AI. Central to Web 5.0."],"r":[]},{"t":"Affiliate marketing","s":"C","m":["2"],"c":"M2","d":["Earning a commission by promoting another company's product through a unique link or code."],"r":[]},{"t":"Aggregator","s":"C","m":["2"],"c":"M2","d":["A stakeholder that bundles and curates content from many sources for specific audiences, such as a news app that collects headlines."],"r":[]},{"t":"Agile","s":"C","m":["2","3"],"c":"M2","d":["An iterative, flexible project management approach that delivers value in small increments and adapts to change through stakeholder collaboration."],"r":[]},{"t":"Agile project management","s":"G","m":["2"],"c":"M2","d":["Flexible, iterative approach to managing digital projects, allowing teams to adapt quickly to change."],"r":[]},{"t":"AI (Artificial Intelligence)","s":"G","m":["1"],"c":"M1","d":["Machines performing intelligent tasks, from image recognition to natural language processing."],"r":[]},{"t":"AI-generated content","s":"C","m":["2"],"c":"M2","d":["Text, images, audio or video produced fully or partly by artificial intelligence tools; an emerging trend transforming creation, personalisation and distribution."],"r":[]},{"t":"Algorithm (platform)","s":"G","m":["1"],"c":"M1","d":["Step-by-step computational process used to analyse data and automate decision-making.","A set of rules a platform uses to decide which content to show each user and in what order in a feed."],"r":[]},{"t":"Alt text","s":"C","m":["1"],"c":"M1","d":["A short written description attached to an image so screen readers can describe it and search engines can understand it."],"r":[]},{"t":"Analogue","s":"C","m":["1"],"c":"M1","d":["A continuous signal or physical recording that varies smoothly, such as a vinyl record groove or a film negative. Copies lose quality each generation."],"r":[]},{"t":"Analysis","s":"C","m":["3"],"c":"M3","d":["Gathering and studying information about the problem, the users and the context so that you understand what is really needed."],"r":[]},{"t":"Analytics","s":"G","m":["2"],"c":"M2","d":["Process of collecting and interpreting data to measure performance and user behaviour.","The collection and analysis of data about how audiences find and use content, for example views, watch time and click-through rate."],"r":[]},{"t":"Angel investor","s":"C","m":["2"],"c":"M2","d":["A wealthy individual who invests personal money in an early-stage business, usually in exchange for equity and often with mentoring."],"r":[]},{"t":"Angular (conic) gradient","s":"C","m":["3"],"c":"M3","d":["A gradient that sweeps around a centre point like the hands of a clock."],"r":[]},{"t":"Animatic","s":"C","m":["3"],"c":"M3","d":["Storyboard panels timed to a scratch soundtrack to test pace and length before filming."],"r":[]},{"t":"APA style","s":"X","m":["1"],"c":"M1","d":["The American Psychological Association citation style, used for the Digital Media SBA: author and year, e.g. (Brooks, 2024)."],"r":[]},{"t":"API (Application Programming Interface)","s":"G","m":["2"],"c":"M2","d":["Set of rules enabling different software systems to communicate and share data with each other."],"r":[]},{"t":"App","s":"G","m":["1"],"c":"M1","d":["Software application designed for specific functions, typically on mobile or web platforms."],"r":[]},{"t":"AR (Augmented Reality)","s":"G","m":["1"],"c":"M1","d":["Overlays digital elements onto real-world environments, blending physical and digital experiences."],"r":[]},{"t":"Ascender and descender","s":"C","m":["3"],"c":"M3","d":["The parts of lowercase letters that rise above the x-height (b, d, h) or drop below the baseline (g, p, y)."],"r":[]},{"t":"Aspect ratio","s":"G","m":["3","1"],"c":"M3","d":["The proportional relationship between an image or screen's width and height. Examples: 16:9 (widescreen), 4:3, 1:1.","Ratio of width to height in an image or video, e.g. 16:9 for widescreen.","The ratio of width to height of an image or video frame, such as 16:9 (landscape), 9:16 (vertical), 1:1 (square) or 4:5 (portrait feed)."],"r":[]},{"t":"Assistive technology","s":"G","m":["1"],"c":"M1","d":["Devices and software supporting users with additional needs.","Tools that help people with disabilities use digital media, such as screen readers, captions, voice control and switch devices."],"r":[]},{"t":"Audience segmentation","s":"C","m":["2"],"c":"M2","d":["Dividing an audience into groups that share characteristics such as age, location, interests or device use, so content can be targeted."],"r":[]},{"t":"Auteur theory","s":"C","m":["1"],"c":"M1","d":["The idea that the director is the true author of a film, whose personal vision shapes it."],"r":[]},{"t":"Automation","s":"G","m":["1"],"c":"M1","d":["Use of technology to perform tasks automatically, reducing manual effort."],"r":[]},{"t":"B-roll","s":"C","m":["3"],"c":"M3","d":["Supporting footage cut into a video over the main footage (A-roll) to illustrate what is being said and to hide edits."],"r":[]},{"t":"Backlighting","s":"C","m":["3"],"c":"M3","d":["Light placed behind the subject, facing the camera, creating a rim light or silhouette that separates the subject from the background."],"r":[]},{"t":"Balance","s":"C","m":["3"],"c":"M3","d":["The distribution of visual weight in a design: symmetrical, asymmetrical or radial."],"r":[]},{"t":"Bandwidth","s":"G","m":["1"],"c":"M1","d":["The maximum amount of data that can be transferred over a network connection in a given time, usually measured in bits per second. Example: A 100 Mbps internet plan.","Capacity of a network to transfer data; higher bandwidth enables faster connections.","The amount of data that can be transmitted over a connection in a given time, usually measured in megabits per second (Mbps)."],"r":[]},{"t":"Baseline","s":"C","m":["3"],"c":"M3","d":["The invisible line on which letters sit."],"r":[]},{"t":"Baseline grid","s":"C","m":["3"],"c":"M3","d":["Horizontal guides set to the body-text leading so text aligns across columns."],"r":[]},{"t":"Bit depth","s":"C","m":["3"],"c":"M3","d":["The number of bits used to store each sample (audio) or each colour channel (image). Higher bit depth gives more dynamic range or more colours: 16-bit and 24-bit audio; 8-bit and 16-bit per channel images."],"r":[]},{"t":"Bit rate","s":"X","m":["3"],"c":"M3","d":["The amount of data used per second of audio or video (e.g. 128 kbps); higher bit rates give better quality and bigger files."],"r":[]},{"t":"Bitrate","s":"G","m":["3"],"c":"M3","d":["Amount of data processed per second in audio or video; affects quality and file size.","The amount of data used per second of audio or video, e.g. 192 kbps for MP3 or 10 Mbps for 1080p video. Higher bitrate usually means higher quality and bigger files."],"r":[]},{"t":"Bleed","s":"C","m":["3"],"c":"M3","d":["Artwork extended beyond the trim line (usually 3 mm) so no white edge appears after cutting."],"r":[]},{"t":"Blend mode","s":"C","m":["3"],"c":"M3","d":["A setting that controls how a layer mixes with those below it, such as multiply, screen or overlay."],"r":[]},{"t":"Blockbuster","s":"C","m":["1"],"c":"M1","d":["A high-budget film released widely at once with heavy advertising and merchandising, a model set by Jaws (1975) and Star Wars (1977)."],"r":[]},{"t":"Blockchain","s":"C","m":["1"],"c":"M1","d":["A shared digital ledger copied across many computers, used to record transactions or ownership without a central authority."],"r":[]},{"t":"Blocking","s":"C","m":["3"],"c":"M3","d":["The planned positions and movements of performers in a scene, agreed in rehearsal."],"r":[]},{"t":"Blog","s":"G","m":["3"],"c":"M3","d":["Online platform for publishing written content, often in a chronological, conversational format."],"r":[]},{"t":"Branched network model","s":"C","m":["3"],"c":"M3","d":["An implementation model in which the work splits into parallel paths or options that are developed separately and later combined or chosen between."],"r":[]},{"t":"Brand partnership","s":"C","m":["2"],"c":"M2","d":["A deal in which a creator produces sponsored content or affiliate promotions for a brand that suits their audience."],"r":[]},{"t":"Broadband","s":"G","m":["1"],"c":"M1","d":["High-speed, always-on internet access that carries large amounts of data. Example: Fibre, cable or DSL internet."],"r":[]},{"t":"Budget variance","s":"C","m":["2"],"c":"M2","d":["The difference between the amount planned in a budget and the amount actually spent, identified when comparing budget vs actuals."],"r":[]},{"t":"Butterfly (Paramount) lighting","s":"C","m":["3"],"c":"M3","d":["Light directly in front of and above the subject, pointing down, casting a small butterfly-shaped shadow under the nose; used for glamour and beauty portraits."],"r":[]},{"t":"Camera angle","s":"C","m":["3"],"c":"M3","d":["The height and direction of the camera relative to the subject: eye level (neutral), high (vulnerable), low (powerful), bird's-eye, worm's-eye or Dutch."],"r":[]},{"t":"Caribbean market access","s":"C","m":["1"],"c":"M1","d":["A platform consideration: whether a Caribbean audience can reach and use a platform, given data costs, payment and delivery options, regional restrictions and languages."],"r":[]},{"t":"Catchlight","s":"C","m":["3"],"c":"M3","d":["The small reflection of a light source in the subject's eyes, which makes a portrait look alive."],"r":[]},{"t":"CC0","s":"C","m":["1"],"c":"M1","d":["A Creative Commons public domain dedication: the creator waives their rights as far as the law allows, so anyone may use the work without conditions."],"r":[]},{"t":"Chiaroscuro","s":"C","m":["3"],"c":"M3","d":["An extreme contrast of light and dark, from painting, used in film for intense drama."],"r":[]},{"t":"Chronophotography","s":"C","m":["1"],"c":"M1","d":["Photographing successive phases of movement, as Muybridge and Marey did in the 1870s and 1880s."],"r":[]},{"t":"Cinématographe","s":"C","m":["1"],"c":"M1","d":["The Lumière brothers' combined camera and projector, used for the first paying public screening in 1895."],"r":[]},{"t":"Civic participation","s":"C","m":["1"],"c":"M1","d":["Citizens organising, petitioning and mobilising around causes; digital media gives communities a voice and supports grassroots movements."],"r":[]},{"t":"Client","s":"C","m":["2"],"c":"M2","d":["A business or organisation that commissions digital media work, such as a website, a campaign or branded video."],"r":[]},{"t":"Clipping","s":"C","m":["3"],"c":"M3","d":["Distortion that occurs when an audio signal exceeds the maximum level (0 dBFS) and the peaks are cut off. It cannot be repaired properly afterwards."],"r":[]},{"t":"Closed captions","s":"C","m":["1"],"c":"M1","d":["On-screen text of the speech and important sounds in a video, which viewers can switch on or off."],"r":[]},{"t":"Closure","s":"C","m":["3"],"c":"M3","d":["The Gestalt tendency to complete an incomplete shape in the mind."],"r":[]},{"t":"Cloud collaboration","s":"G","m":["2"],"c":"M2","d":["Tools enabling real-time teamwork online, regardless of physical location.","Using online tools such as shared documents, messaging and project boards so that team members can co-create in real time across locations and time zones."],"r":[]},{"t":"Cloud computing","s":"G","m":["2","3"],"c":"M2","d":["Delivery of computing services (servers, storage, software) over the internet.","Using storage, software and processing power delivered over the internet from remote data centres instead of from your own device."],"r":[]},{"t":"Cloud storage","s":"G","m":["2","1"],"c":"M2","d":["Saving files on remote internet-connected servers so they can be accessed from any device. Examples: Google Drive, OneDrive, iCloud.","Online file storage and retrieval, accessible from any connected device."],"r":[]},{"t":"Codec","s":"G","m":["3","1"],"c":"M3","d":["Short for coder-decoder: software or hardware that compresses (encodes) and decompresses (decodes) audio or video. Examples: H.264 for video, MP3 for audio.","Tool used to encode and decode media files, enabling playback and transmission of audio and video.","Software that compresses and decompresses audio or video, e.g. H.264 (AVC), H.265 (HEVC) or AAC."],"r":[]},{"t":"Colour gamut","s":"C","m":["3"],"c":"M3","d":["The full range of colours a device, such as a screen or printer, can reproduce. Printers usually have a smaller gamut than screens."],"r":[]},{"t":"Colour gradient","s":"C","m":["3"],"c":"M3","d":["A gradual blend from one colour to another, or through several, used to add depth, guide attention or give a modern look."],"r":[]},{"t":"Colour grading","s":"C","m":["3"],"c":"M3","d":["Creative adjustment of colour and tone in video editing to create a mood or style, done after colour correction has fixed exposure and white balance."],"r":[]},{"t":"Colour harmony","s":"C","m":["3"],"c":"M3","d":["A set of colours chosen by their positions on the colour wheel: complementary, analogous, triadic, split-complementary or monochromatic."],"r":[]},{"t":"Colour profile","s":"G","m":["1"],"c":"M1","d":["A set of data defining how colours are represented across devices so they look consistent. Common models: RGB (screens and web display), CMYK (print production), sRGB (standard for web images). Example: sRGB for web; CMYK for printing.","A standard set of data that describes how colours should be displayed or printed, such as sRGB for screens or a CMYK profile for print."],"r":[]},{"t":"Colour vision deficiency","s":"C","m":["3"],"c":"M3","d":["Reduced ability to tell some colours apart, often called colour blindness; it affects about 1 in 12 men and 1 in 200 women, most often with red and green."],"r":[]},{"t":"Column grid","s":"C","m":["3"],"c":"M3","d":["A layout framework of columns separated by gutters inside margins; 12 columns are common because they divide into halves, thirds, quarters and sixths."],"r":[]},{"t":"Common region","s":"C","m":["3"],"c":"M3","d":["The Gestalt tendency to group items that share an enclosed area, such as a box or card."],"r":[]},{"t":"Community Wi-Fi","s":"C","m":["1"],"c":"M1","d":["A free or low-cost public wireless hotspot, often at a library, school or community centre, that gives access to people without home Internet."],"r":[]},{"t":"Compositing","s":"C","m":["3"],"c":"M3","d":["Combining several images into one believable scene by matching light direction, colour temperature, perspective and sharpness."],"r":[]},{"t":"Compression","s":"G","m":["3","1"],"c":"M3","d":["Reducing file size by removing or re-encoding data. Lossy compression discards some data permanently; lossless keeps all original data. Examples: JPEG (lossy), PNG (lossless).","Reduction of file size for efficient storage and transmission without significant quality loss."],"r":[]},{"t":"Compression / codec","s":"C","m":["1"],"c":"M1","d":["Compression reduces file size: lossy (JPEG, MP3) discards some data, lossless (PNG, FLAC, ZIP) keeps it all. A codec (coder-decoder) is the method used to compress and decompress audio or video, such as H.264 or AAC."],"r":[]},{"t":"Computer-generated imagery (CGI)","s":"C","m":["1"],"c":"M1","d":["Images and effects created digitally, used for creatures, environments and fully animated films."],"r":[]},{"t":"Cone cells","s":"C","m":["3"],"c":"M3","d":["Light-sensitive cells in the retina. Humans have three types, roughly sensitive to red, green and blue light; the brain combines their signals into the colours we see."],"r":[]},{"t":"Container format","s":"X","m":["3"],"c":"M3","d":["The file wrapper that holds video, audio, subtitles and metadata together, e.g. MP4, MOV, MKV."],"r":[]},{"t":"Content delivery network (CDN)","s":"C","m":["2"],"c":"M2","d":["A network of servers in many locations that stores copies of content close to users so that it loads quickly."],"r":[]},{"t":"Content integration","s":"G","m":["1"],"c":"M1","d":["Combining content from different sources, formats or systems into one unified experience or platform. Example: A news site embedding a YouTube video, a tweet and a map.","Combining content from different sources or media into one unified product or experience, such as a news site that embeds video, maps and social posts."],"r":[]},{"t":"Content management system (CMS)","s":"G","m":["1","2"],"c":"M1","d":["Software for creating, managing and publishing digital content, e.g. WordPress, Squarespace.","Software that lets users create, edit and publish web content without coding, such as WordPress."],"r":[]},{"t":"Content strategy","s":"G","m":["2"],"c":"M2","d":["Planning and managing digital content to meet audience needs and business goals."],"r":[]},{"t":"Contingency","s":"C","m":["2"],"c":"M2","d":["An amount added to a budget, often about 10%, to cover unexpected costs."],"r":[]},{"t":"Continuity editing","s":"C","m":["3"],"c":"M3","d":["The \"invisible\" editing style that keeps space and time seamless, using the 180-degree rule, eyeline matches and match on action."],"r":[]},{"t":"Continuous learning","s":"C","m":["2"],"c":"M2","d":["Treating learning as a lifelong practice, through regular upskilling, following industry trends and building a learning habit."],"r":[]},{"t":"Convergence","s":"G","m":["1"],"c":"M1","d":["The merging of previously separate technologies, devices, media and industries into a single system or device. Example: A smartphone that is a phone, camera, music player, TV and computer.","Integration of multiple media forms (text, audio, video) into unified digital platforms.","The coming together of separate media, technologies and industries on one device or platform, for example a smartphone that is a camera, music player, TV and telephone."],"r":[]},{"t":"Copyleft","s":"C","m":["1"],"c":"M1","d":["A licensing approach that lets people share and modify a work provided derivatives are shared on the same terms, for example Creative Commons ShareAlike or the GPL."],"r":[]},{"t":"Copyright","s":"G","m":["1"],"c":"M1","d":["Legal protection for original creative works, granting creators exclusive rights over their content.","The legal right of a creator to control the copying, sharing and adaptation of an original work such as a song, photo, video, book or software."],"r":[]},{"t":"Counter and bowl","s":"C","m":["3"],"c":"M3","d":["The bowl is the curved stroke enclosing a space in letters such as b and o; the counter is the space inside."],"r":[]},{"t":"Crane (jib) shot","s":"C","m":["3"],"c":"M3","d":["A shot in which the camera rises or descends on an arm, often for grand openings and endings."],"r":[]},{"t":"Creative Commons","s":"X","m":["1"],"c":"M1","d":["A set of free licences that let creators say how others may reuse their work, e.g. CC BY requires credit to the creator."],"r":[]},{"t":"Creative Commons (CC)","s":"G","m":["1"],"c":"M1","d":["Licensing system allowing creators to share content under defined terms and conditions.","A set of free, standard licences that let creators keep copyright while allowing others to use their work on stated conditions, such as BY (attribution), SA (share-alike), NC (non-commercial) and ND (no derivatives)."],"r":[]},{"t":"Creative design process","s":"C","m":["3"],"c":"M3","d":["A structured sequence of stages that turns a problem or idea into a tested solution. Its seven stages are acceptance, analysis, definition, ideation, selection, implementation and evaluation."],"r":[]},{"t":"Creator","s":"C","m":["2"],"c":"M2","d":["An individual who generates original content, such as videos, articles, podcasts or graphics, often independently through social platforms and the creator economy."],"r":[]},{"t":"Creator economy","s":"C","m":["2"],"c":"M2","d":["The economy built around independent creators who make, distribute and earn from their own content through digital platforms."],"r":[]},{"t":"Cross-cutting","s":"C","m":["3"],"c":"M3","d":["Alternating between two actions happening at the same time, often to build suspense; also called parallel editing."],"r":[]},{"t":"Cross-platform marketing","s":"G","m":["2"],"c":"M2","d":["Publishing and promoting content across multiple digital platforms to maximise reach and audience engagement."],"r":[]},{"t":"Crowdfunding","s":"C","m":["2"],"c":"M2","d":["Raising small amounts of money from many people, usually online, in return for rewards, products, a share or simply goodwill."],"r":[]},{"t":"Cultural awareness","s":"C","m":["2"],"c":"M2","d":["Understanding and respecting diverse perspectives, traditions and values when creating and working with others."],"r":[]},{"t":"Cyberbullying","s":"C","m":["1"],"c":"M1","d":["Repeated online harassment, humiliation or exclusion targeting an individual, often amplified by shares and likes."],"r":[]},{"t":"Cybercrime","s":"G","m":["1"],"c":"M1","d":["Illegal activity conducted using digital technology, including hacking, fraud and data theft."],"r":[]},{"t":"Cybersecurity","s":"G","m":["1"],"c":"M1","d":["Protection of computer systems, networks and data from digital attacks, unauthorised access and damage. As digital media expands, it becomes an increasingly critical skill for all practitioners."],"r":[]},{"t":"Cyberstalking","s":"C","m":["1"],"c":"M1","d":["Persistent online monitoring, unwanted contact or threats directed at a person, using location data, social posts and tracking tools."],"r":[]},{"t":"Data analytics","s":"C","m":["1"],"c":"M1","d":["Collecting and analysing data such as views, clicks and watch time to understand audiences and make decisions."],"r":[]},{"t":"Data breach","s":"C","m":["1"],"c":"M1","d":["An incident in which confidential data, such as card numbers or health records, is accessed or released without authorisation."],"r":[]},{"t":"Data privacy","s":"G","m":["1"],"c":"M1","d":["Protection of personal information from unauthorised access or misuse."],"r":[]},{"t":"Data protection","s":"G","m":["1"],"c":"M1","d":["Safeguarding sensitive data through policies, encryption and secure storage practices."],"r":[]},{"t":"Data visualisation","s":"G","m":["1"],"c":"M1","d":["Graphical display of data (charts, graphs, infographics) to communicate insights clearly."],"r":[]},{"t":"Data-ink ratio","s":"C","m":["1"],"c":"M1","d":["Tufte's principle that most of the ink (or pixels) in a chart should show data, not decoration."],"r":[]},{"t":"Data, information and knowledge","s":"C","m":["1"],"c":"M1","d":["Data is raw facts; information is data given a context; knowledge is information personalised for your needs and used to make a choice."],"r":[]},{"t":"Debt financing","s":"C","m":["2"],"c":"M2","d":["Raising money by borrowing, for example a bank loan, which must be repaid with interest; the owner keeps full ownership."],"r":[]},{"t":"Decentralisation","s":"C","m":["1"],"c":"M1","d":["Spreading control of data or services across many computers instead of one company, for example through blockchain."],"r":[]},{"t":"Deepfake","s":"G","m":["1"],"c":"M1","d":["AI-generated manipulated media (video, audio or images) that falsely depicts real people.","AI-generated or AI-altered video, image or audio that realistically shows a person saying or doing something they never did."],"r":[]},{"t":"Definition","s":"C","m":["3"],"c":"M3","d":["Stating the problem clearly and precisely, usually as a problem statement with success criteria."],"r":[]},{"t":"Design thinking","s":"C","m":["3"],"c":"M3","d":["A human-centred approach to problem solving with five stages: empathise, define, ideate, prototype and test."],"r":[]},{"t":"Dial-up","s":"C","m":["1"],"c":"M1","d":["An early Internet connection made through a modem over a telephone line, with speeds of up to 56 kbps; it tied up the phone line while online."],"r":[]},{"t":"Didone","s":"C","m":["3"],"c":"M3","d":["A Modern serif style with vertical stress, extreme thick-thin contrast and hairline serifs, such as Bodoni and Didot."],"r":[]},{"t":"Digital Art","s":"G","m":["1"],"c":"M1","d":["Art created using computers and software, such as design apps, graphics tablets and styluses. It exists in electronic form as digital files that are easy to edit and can be copied and shared without losing quality. Example: An illustration drawn in Adobe Illustrator or Procreate."],"r":[]},{"t":"Digital campaign","s":"G","m":["2"],"c":"M2","d":["Coordinated digital promotion across channels to achieve a specific marketing or communication goal."],"r":[]},{"t":"Digital citizenship","s":"G","m":["1"],"c":"M1","d":["Responsible, ethical use of technology and participation in online communities.","Using technology safely, respectfully, responsibly and ethically, and taking part positively in online communities."],"r":[]},{"t":"Digital divide","s":"C","m":["1","2"],"c":"M1","d":["Unequal access to devices, bandwidth and digital skills, so that not everyone benefits equally from digital media."],"r":[]},{"t":"Digital ecosystem","s":"G","m":["2"],"c":"M2","d":["A system of interconnected platforms, creators, users and technologies that interact and depend on each other to produce and distribute digital content."],"r":[]},{"t":"Digital entrepreneurship","s":"G","m":["2"],"c":"M2","d":["Building and running a business using digital platforms, tools and networks as the primary means of operation and revenue generation."],"r":[]},{"t":"Digital footprint","s":"G","m":["1"],"c":"M1","d":["The record of a person's online activity: data left behind through browsing, posting and interactions.","The permanent trail of data you leave online through posts, searches, comments, photos and accounts."],"r":[]},{"t":"Digital generation","s":"C","m":["2"],"c":"M2","d":["Young people whose childhood and adolescence have been shaped by digital media; they have rights (such as privacy and safety) and needs (such as access and digital literacy) in the digital environment."],"r":[]},{"t":"Digital gerrymandering","s":"C","m":["1"],"c":"M1","d":["Algorithmic filtering that steers what certain people see online, shaping major decisions such as voting by creating information bubbles and amplifying polarising content."],"r":[]},{"t":"Digital immigrant","s":"G","m":["2"],"c":"M2","d":["A person who adopted digital technology later in life, rather than growing up with it.","A person who adopted digital technology later in life and may still show habits from an earlier, non-digital way of working, such as printing emails."],"r":[]},{"t":"Digital literacy","s":"G","m":["1","2"],"c":"M1","d":["Ability to use, evaluate and create digital content effectively and critically.","The skills and confidence to find, evaluate, create and communicate information safely using digital technology."],"r":[]},{"t":"Digital media","s":"G","m":["1"],"c":"M1","d":["Content (text, images, audio, video, animation) created, stored, edited and shared in digital (binary) form. Digital media is the foundation of all terms in this glossary. Examples: a photo saved as a JPEG, an MP3 song.","A form of electronic media where data are stored in digital (as opposed to analogue) form, as binary code that computers can create, edit, store and share."],"r":[]},{"t":"Digital media ecosystem","s":"C","m":["2"],"c":"M2","d":["The interconnected network of people, organisations, platforms, technologies and rules through which digital media is created, distributed, paid for, consumed and regulated."],"r":[]},{"t":"Digital media platform (DMP)","s":"C","m":["1"],"c":"M1","d":["A digitised platform for media delivery of video, audio and/or data to multiple networks, such as telco, cable, satellite, digital terrestrial broadcasting and the Internet."],"r":[]},{"t":"Digital native","s":"G","m":["2"],"c":"M2","d":["A person raised with digital technology from an early age, for whom it is a natural part of life.","A person who has grown up surrounded by digital technology and uses it fluently as a normal part of daily life; the term was popularised by Marc Prensky in 2001."],"r":[]},{"t":"Digital portfolio","s":"G","m":["3"],"c":"M3","d":["A curated collection of digital work showcasing skills, projects and creative output."],"r":[]},{"t":"Digital projection (DCP)","s":"C","m":["1"],"c":"M1","d":["Showing films in cinemas from digital files (a Digital Cinema Package) instead of film prints."],"r":[]},{"t":"Digital proposal portfolio","s":"C","m":["3"],"c":"M3","d":["An organised digital collection that documents a project from research and ideation through planning, production and evaluation to the final solution."],"r":[]},{"t":"Digital publishing","s":"G","m":["3","1"],"c":"M3","d":["Creating and distributing content (books, magazines, newspapers, journals) in digital formats for screens, instead of or alongside print. Examples: an ebook, an online magazine, a PDF newsletter.","Creating and sharing content in digital formats: ebooks, websites, online articles."],"r":[]},{"t":"Digital rights","s":"C","m":["2"],"c":"M2","d":["Human rights as they apply online, including privacy, freedom of expression, access to information, protection from harm and participation."],"r":[]},{"t":"Digital rights management (DRM)","s":"G","m":["1"],"c":"M1","d":["Technology that controls access to and use of digital content, protecting creators' intellectual property.","Technology that controls access to, copying of and distribution of digital content, such as streaming restrictions or e-books that cannot be copied."],"r":[]},{"t":"Digital workflow","s":"G","m":["1"],"c":"M1","d":["The sequence of steps and tools used in digital content production, from creation to publication."],"r":[]},{"t":"Digitization","s":"G","m":["1"],"c":"M1","d":["The process of converting analogue content (film, print, audio) into a digital format."],"r":[]},{"t":"Disintermediation","s":"C","m":["2"],"c":"M2","d":["The removal of traditional middlemen from a value chain, for example a musician releasing songs directly to listeners online without a record label."],"r":[]},{"t":"Disposition","s":"C","m":["2"],"c":"M2","d":["A habitual attitude or way of behaving, such as curiosity, resilience or openness to feedback."],"r":[]},{"t":"Disruption","s":"C","m":["1"],"c":"M1","d":["When a new technology or business model changes or replaces established industries, for example streaming replacing video rental."],"r":[]},{"t":"Disruption risk","s":"C","m":["2"],"c":"M2","d":["The danger that a change in one element of the ecosystem, such as a new algorithm, regulation or technology, reshapes the entire value chain."],"r":[]},{"t":"Dissolve","s":"C","m":["3"],"c":"M3","d":["A transition in which one shot gradually replaces another, often showing time passing."],"r":[]},{"t":"Distributor","s":"C","m":["2"],"c":"M2","d":["An entity that delivers content to audiences through networks, content delivery networks, internet service providers and digital syndication channels."],"r":[]},{"t":"Dodge and burn","s":"C","m":["3"],"c":"M3","d":["Retouching techniques that lighten (dodge) or darken (burn) selected areas of an image."],"r":[]},{"t":"Dolly and tracking shot","s":"C","m":["3"],"c":"M3","d":["Movements in which the whole camera travels: a dolly moves towards or away from the subject; a tracking shot moves alongside it."],"r":[]},{"t":"Donation","s":"C","m":["2"],"c":"M2","d":["A gift of money with no repayment or reward expected, common for community and non-profit media."],"r":[]},{"t":"Downloadable Media","s":"G","m":["1"],"c":"M1","d":["Digital files transferred and saved to a device so they can be used offline, later or repeatedly. Examples: a purchased MP3 music file, a PDF ebook, an app installed from an app store."],"r":[]},{"t":"Doxxing","s":"C","m":["1"],"c":"M1","d":["Publishing someone's private details, such as a home address, workplace or phone number, online to expose and endanger them."],"r":[]},{"t":"DPI / PPI","s":"C","m":["3"],"c":"M3","d":["Dots or pixels per inch. Print work is normally prepared at 300 DPI at its final printed size; on screens, the pixel dimensions are what matter."],"r":[]},{"t":"Dutch (canted) angle","s":"C","m":["3"],"c":"M3","d":["A shot with the camera tilted so the horizon is diagonal, suggesting unease, instability or danger."],"r":[]},{"t":"Early adopters","s":"C","m":["1"],"c":"M1","d":["The next 13.5% of adopters: opinion leaders who see the strategic value of a new technology and influence others."],"r":[]},{"t":"Early majority","s":"C","m":["1"],"c":"M1","d":["About 34% of adopters, who take up a technology once its benefits are proven."],"r":[]},{"t":"Elevator pitch","s":"C","m":["2"],"c":"M2","d":["A brief, persuasive summary of an idea, short enough to deliver in about 30 to 60 seconds."],"r":[]},{"t":"Em dash and en dash","s":"C","m":["3"],"c":"M3","d":["The em dash (—) marks a break in a sentence; the en dash (–) marks a range, such as 9–5."],"r":[]},{"t":"Emerging technologies","s":"G","m":["1"],"c":"M1","d":["New and developing technologies such as AI, AR, VR and blockchain that are reshaping the digital media landscape."],"r":[]},{"t":"Emotional web (Web 5.0)","s":"C","m":["1"],"c":"M1","d":["A partly speculative stage: the sensory and emotional web, in which systems respond to human emotions and sensory input. Also called the Unseen Web."],"r":[]},{"t":"End user","s":"C","m":["2"],"c":"M2","d":["The person who finally consumes, shares and responds to content at the end of the value chain."],"r":[]},{"t":"Engagement","s":"G","m":["2"],"c":"M2","d":["The level of user interaction with digital content: likes, shares, comments and time spent."],"r":[]},{"t":"Engagement / analytics","s":"C","m":["1"],"c":"M1","d":["Engagement is how users interact with content (likes, comments, shares, watch time). Analytics are the data and tools used to measure it."],"r":[]},{"t":"Equity financing","s":"C","m":["2"],"c":"M2","d":["Raising money by selling a share of ownership in the business to investors such as angels or venture capitalists."],"r":[]},{"t":"Ethical digital practice","s":"G","m":["1"],"c":"M1","d":["Responsible use of digital tools and platforms, including respecting privacy, avoiding plagiarism and promoting inclusivity."],"r":[]},{"t":"Ethical judgement","s":"C","m":["2"],"c":"M2","d":["Making principled decisions about content, data, intellectual property and professional conduct."],"r":[]},{"t":"Ethical representation","s":"C","m":["1"],"c":"M1","d":["Showing people and cultures fairly: avoiding stereotypes, getting consent and crediting sources and people."],"r":[]},{"t":"Evaluation","s":"C","m":["3"],"c":"M3","d":["Judging how well the solution meets the success criteria and the users' needs, and deciding what to improve."],"r":[]},{"t":"Executive summary","s":"C","m":["2"],"c":"M2","d":["A short overview at the start of a proposal that summarises the whole proposal so a busy reader can grasp it quickly."],"r":[]},{"t":"Export / render","s":"X","m":["3"],"c":"M3","d":["Turning an edited project into a finished file in a chosen format and settings."],"r":[]},{"t":"Eyeline match","s":"C","m":["3"],"c":"M3","d":["Cutting so that the direction a character looks matches the position of what they are looking at in the next shot."],"r":[]},{"t":"Fair dealing / fair use","s":"C","m":["1"],"c":"M1","d":["Limited exceptions that allow use of copyright material without permission for purposes such as research, criticism, review, news reporting or teaching. Commonwealth Caribbean law generally uses \"fair dealing\"; the United States uses \"fair use\"."],"r":[]},{"t":"Fair use","s":"G","m":["1"],"c":"M1","d":["A legal doctrine allowing limited use of copyrighted material without permission, for purposes such as education or commentary."],"r":[]},{"t":"Feathering","s":"C","m":["3"],"c":"M3","d":["Pointing the light slightly away from the subject so the softer edge of the beam lights them, reducing harsh shadows."],"r":[]},{"t":"Feedback loop","s":"C","m":["3"],"c":"M3","d":["A planned point where work is reviewed and the results are fed back into an earlier stage to improve it."],"r":[]},{"t":"Fibre-optic broadband","s":"C","m":["1"],"c":"M1","d":["High-speed Internet that sends data as pulses of light through glass fibres; fast, reliable and, when buried, more resistant to storms."],"r":[]},{"t":"Fidelity (lo-fi, mid-fi, hi-fi)","s":"C","m":["3"],"c":"M3","d":["How close a design is to the finished product: low fidelity is rough and quick (sketches, grey boxes), mid fidelity is precise but plain, and high fidelity looks and behaves like the final product."],"r":[]},{"t":"Figure / ground","s":"C","m":["3"],"c":"M3","d":["The perception of an object (figure) as separate from its background (ground)."],"r":[]},{"t":"File Format","s":"G","m":["1"],"c":"M1","d":["The way data is structured and encoded in a file, usually shown by its extension. Examples: .jpg, .mp4, .html."],"r":[]},{"t":"Film language","s":"C","m":["3"],"c":"M3","d":["The system of visual and sound choices (shots, angles, movement, lighting, editing and sound) that filmmakers use to communicate meaning."],"r":[]},{"t":"Filter bubble","s":"C","m":["1"],"c":"M1","d":["An information bubble created when algorithms show people mainly content that matches their past behaviour, hiding other views."],"r":[]},{"t":"Financial literacy","s":"C","m":["2"],"c":"M2","d":["A basic understanding of budgeting, pricing, revenue models and financial planning for creative projects."],"r":[]},{"t":"Frame rate","s":"G","m":["1","3"],"c":"M1","d":["The number of frames displayed per second (fps) in video or animation. Examples: 24 fps (film), 30 fps, 60 fps.","The number of frames displayed per second in video; higher frame rates produce smoother motion.","The number of still frames shown per second in video or animation (fps), such as 24, 30 or 60."],"r":[]},{"t":"Frame rate (fps)","s":"X","m":["3"],"c":"M3","d":["The number of still images shown per second in video, e.g. 24 fps for a film look, 30 fps for web video."],"r":[]},{"t":"Freelancing","s":"C","m":["2"],"c":"M2","d":["Working on short-term, project-based contracts for multiple clients rather than as a permanent employee."],"r":[]},{"t":"Generation Alpha","s":"C","m":["2"],"c":"M2","d":["People born after about 2010 (some sources say 2013), growing up with even more advanced technology such as tablets, smart speakers and AI tools."],"r":[]},{"t":"Generation Z","s":"C","m":["2"],"c":"M2","d":["People born roughly 1997 to 2012, immersed in digital technology since birth."],"r":[]},{"t":"Generative AI","s":"G","m":["1"],"c":"M1","d":["AI systems that create new content (text, images, audio or video) based on patterns learned from data."],"r":[]},{"t":"Generative AI / AI hallucination","s":"C","m":["1"],"c":"M1","d":["Generative AI creates new text, images, audio, video or code from a prompt. A hallucination is when it produces false or invented information and presents it confidently as fact."],"r":[]},{"t":"Gestalt principles","s":"C","m":["3"],"c":"M3","d":["Rules describing how the brain groups what it sees: figure/ground, proximity, similarity, closure, continuity, common region and symmetry."],"r":[]},{"t":"GIF","s":"G","m":["3","1"],"c":"M3","d":["Raster format limited to 256 colours; supports simple animation and transparency.","A short looping animated image format widely used in social media and messaging for expression and humour.","An image format limited to 256 colours that supports simple animation and transparency."],"r":[]},{"t":"Gig economy","s":"C","m":["2"],"c":"M2","d":["A labour market in which people take short-term, task-based jobs (gigs), often found through online platforms, instead of permanent employment."],"r":[]},{"t":"Globalisation","s":"C","m":["2"],"c":"M2","d":["The growing interconnection of economies, cultures and labour markets across the world, accelerated by digital communication."],"r":[]},{"t":"Grant","s":"C","m":["2"],"c":"M2","d":["Money given for a specific purpose, usually by a government agency, cultural fund or foundation, that does not have to be repaid but comes with conditions and reporting."],"r":[]},{"t":"Gutter","s":"C","m":["3"],"c":"M3","d":["The space between columns, or between facing pages at the binding."],"r":[]},{"t":"Haptics","s":"C","m":["1"],"c":"M1","d":["Technology that creates a sense of touch, such as vibration or pressure, in a device or controller."],"r":[]},{"t":"Heat map","s":"C","m":["1"],"c":"M1","d":["A chart that uses colour intensity in a grid to show patterns across two dimensions."],"r":[]},{"t":"High-key lighting","s":"C","m":["3"],"c":"M3","d":["Bright, even, low-contrast lighting with few shadows, used for comedy, romance and advertising."],"r":[]},{"t":"HTML","s":"G","m":["1"],"c":"M1","d":["HyperText Markup Language: the standard language for structuring and presenting content on webpages."],"r":[]},{"t":"HTML / CSS / XML","s":"C","m":["1"],"c":"M1","d":["HTML structures web page content; CSS controls its appearance; XML is a markup language for storing and exchanging structured data."],"r":[]},{"t":"Humanist sans serif","s":"C","m":["3"],"c":"M3","d":["A sans serif with warm, pen-influenced shapes and open forms, such as Gill Sans and Frutiger."],"r":[]},{"t":"Hybrid work","s":"C","m":["2"],"c":"M2","d":["A work model that combines some days in the workplace with some days working remotely."],"r":[]},{"t":"Hypermedia","s":"G","m":["1"],"c":"M1","d":["An extension of hypertext in which links also connect to images, audio, video and animation. Example: A web page where clicking an image plays a video.","A linked multimedia system combining text, images, audio and video through interactive hyperlinks."],"r":[]},{"t":"Hypertext","s":"G","m":["1"],"c":"M1","d":["Text containing links (hyperlinks) that let the reader jump to other text or documents. Example: Wikipedia articles linking to related articles.","Text with embedded links that connect to other documents or resources, forming the basis of the web."],"r":[]},{"t":"Hypertext / hypermedia","s":"C","m":["1"],"c":"M1","d":["Hypertext is text containing links to other text or pages. Hypermedia extends this so links connect images, audio, video and other media as well as text."],"r":[]},{"t":"Ideation","s":"G","m":["3"],"c":"M3","d":["The creative process of generating, developing and communicating new ideas in a project context.","The generation of many possible ideas or concepts for a digital media solution, before judging them."],"r":[]},{"t":"Immersive media","s":"G","m":["1"],"c":"M1","d":["Media formats such as VR and AR that fully engage users by surrounding them in a digital environment, creating a sense of presence.","Media that surround the user in a simulated environment, such as virtual reality (VR), augmented reality (AR), extended reality (XR) and 360° video."],"r":[]},{"t":"Implementation","s":"C","m":["3"],"c":"M3","d":["Putting the selected idea into action: producing, building and delivering the digital solution."],"r":[]},{"t":"Inciting incident","s":"C","m":["3"],"c":"M3","d":["The event that disrupts the normal world and starts the main story."],"r":[]},{"t":"Inclusivity","s":"C","m":["2"],"c":"M2","d":["Creating content in which diverse audiences see themselves represented, building broader reach and deeper trust."],"r":[]},{"t":"Industrial property","s":"C","m":["1"],"c":"M1","d":["The branch of intellectual property covering patents, trademarks, industrial designs and geographical indications of source."],"r":[]},{"t":"Influencer marketing","s":"G","m":["2"],"c":"M2","d":["Promotion of products or services via online personalities who have established audiences and credibility."],"r":[]},{"t":"Infographic","s":"G","m":["1"],"c":"M1","d":["A visual display of information combining graphics and text to communicate data clearly and engagingly.","A graphic that combines charts, text and images to tell a self-contained story with data."],"r":[]},{"t":"Information architecture","s":"C","m":["3"],"c":"M3","d":["The way content is organised, labelled and linked in a website or app (its hierarchy and navigation paths) so that users can find what they need."],"r":[]},{"t":"Information visualisation","s":"C","m":["1"],"c":"M1","d":["Turning data into charts, maps and graphics so patterns and insights become visible."],"r":[]},{"t":"Infrastructure provider","s":"C","m":["2"],"c":"M2","d":["An organisation that supplies the physical and technical base of the ecosystem, such as undersea cables, mobile networks, data centres and cloud hosting."],"r":[]},{"t":"Innovators","s":"C","m":["1"],"c":"M1","d":["The first 2.5% of adopters in the technology adoption lifecycle: risk-takers who try new tools first."],"r":[]},{"t":"Intellectual property (IP)","s":"G","m":["1"],"c":"M1","d":["Legal rights over creative and intellectual creations, including copyright, patents and trademarks.","Creations of the mind, such as works, inventions, brands, designs and secrets, that the law protects so the creator can control and benefit from them."],"r":[]},{"t":"Interactive media","s":"G","m":["1"],"c":"M1","d":["Media that responds to the user's input so the user can control, navigate or influence the content. Examples: a quiz app, a video game, a clickable infographic.","Media that allows user participation and input, enabling two-way communication between content and audience.","Media that respond to the user's input, such as games, apps, quizzes and virtual tours."],"r":[]},{"t":"Interactivity","s":"G","m":["1"],"c":"M1","d":["The capability of a digital system or media product to respond to user engagement and input in real time.","The ability of the audience to act on the media and change what happens next, for example tapping a hotspot, choosing a path or filtering a chart."],"r":[]},{"t":"Interdependence","s":"C","m":["2"],"c":"M2","d":["The way players in the ecosystem rely on one another: creators on platforms, platforms on advertisers, advertisers on audience data and audiences on infrastructure."],"r":[]},{"t":"Internet of Things (IoT)","s":"C","m":["1"],"c":"M1","d":["Everyday objects such as meters, thermostats, watches and sensors that connect to the Internet and share data."],"r":[]},{"t":"IP address / URL","s":"C","m":["1"],"c":"M1","d":["An IP (Internet Protocol) address is the numerical address of a device on a network. A URL is the human-readable web address of a resource."],"r":[]},{"t":"Iteration","s":"C","m":["2","3"],"c":"M2","d":["The agile phase in which the team improves the work based on review feedback and adjusts resources, timelines and budgets before the next sprint."],"r":[]},{"t":"J-cut and L-cut","s":"C","m":["3"],"c":"M3","d":["Split edits: in a J-cut the next shot's sound starts before its picture; in an L-cut the current sound continues over the next picture."],"r":[]},{"t":"JPEG (JPG)","s":"G","m":["3"],"c":"M3","d":["A widely used compressed image format that balances file size and visual quality for digital distribution.","A lossy compressed image format for photographs; small files, but quality drops each time it is re-saved."],"r":[]},{"t":"Kerning","s":"C","m":["3"],"c":"M3","d":["Adjusting the space between one specific pair of letters, such as AV or To."],"r":[]},{"t":"Key light","s":"C","m":["3"],"c":"M3","d":["The main light in a setup, which creates the main pattern of light and shadow. In one-light photography it is the only light."],"r":[]},{"t":"Kinetoscope","s":"C","m":["1"],"c":"M1","d":["Edison and Dickson's 1891 peep-show machine for one viewer to watch a short film."],"r":[]},{"t":"Kuleshov effect","s":"C","m":["3"],"c":"M3","d":["The finding that audiences read the same shot differently depending on the shot placed next to it."],"r":[]},{"t":"Laggards","s":"C","m":["1"],"c":"M1","d":["The last 16% of adopters, who resist change and adopt last, often only when the old option disappears."],"r":[]},{"t":"Late majority","s":"C","m":["1"],"c":"M1","d":["About 34% of adopters, who take up a technology when it becomes necessary, often because of customer pressure."],"r":[]},{"t":"Latency","s":"G","m":["1"],"c":"M1","d":["The delay between a request being sent and a response being received, measured in milliseconds (ms). Example: Lag in an online game or video call.","The delay between a user's action and the system's response; critical in streaming, gaming and live media.","The delay between sending data and it arriving, measured in milliseconds. Low latency matters for livestreams, video calls and online games."],"r":[]},{"t":"Layer mask","s":"C","m":["3"],"c":"M3","d":["A control that hides or reveals parts of a layer without deleting pixels, so edits stay reversible."],"r":[]},{"t":"Leading","s":"C","m":["3"],"c":"M3","d":["The vertical distance from one baseline to the next; about 120 to 145% of the type size for print body text."],"r":[]},{"t":"Legibility and readability","s":"C","m":["3"],"c":"M3","d":["Legibility is how easily individual characters can be recognised; readability is how comfortably a whole text can be read, depending on how it is set."],"r":[]},{"t":"Licensing","s":"C","m":["2"],"c":"M2","d":["Granting another party permission to use your content, such as a song or video clip, in return for a fee or royalty."],"r":[]},{"t":"Line of action","s":"C","m":["3"],"c":"M3","d":["The line between two characters, or along a movement, that the camera should not cross."],"r":[]},{"t":"Linear editing","s":"C","m":["1"],"c":"M1","d":["An older, tape-based way of editing video in sequence from start to finish. Modern non-linear editing (NLE) lets you work on any part of a timeline in any order."],"r":[]},{"t":"Linear gradient","s":"C","m":["3"],"c":"M3","d":["A gradient that changes colour along a straight line: horizontal, vertical or diagonal."],"r":[]},{"t":"Livestream","s":"G","m":["3"],"c":"M3","d":["Real-time broadcasting of video content over the internet, enabling live audience interaction."],"r":[]},{"t":"Loop lighting","s":"C","m":["3"],"c":"M3","d":["Light 30–45° to the side and slightly above eye level, casting a small loop-shaped nose shadow on the cheek; versatile and flattering."],"r":[]},{"t":"Lossless compression","s":"C","m":["3"],"c":"M3","d":["Compression that makes files smaller without losing any data, e.g. PNG, FLAC and ZIP."],"r":[]},{"t":"Lossy compression","s":"C","m":["3"],"c":"M3","d":["Compression that permanently removes some data to make files smaller, e.g. JPEG, MP3 and H.264 MP4."],"r":[]},{"t":"Low-key lighting","s":"C","m":["3"],"c":"M3","d":["Dark, high-contrast lighting with deep shadows, used for thrillers, film noir and horror."],"r":[]},{"t":"Machine-readable format","s":"C","m":["1"],"c":"M1","d":["A data format a computer can process directly, such as CSV or JSON. A scanned image of a table is not machine-readable."],"r":[]},{"t":"Magic lantern","s":"C","m":["1"],"c":"M1","d":["An early projector (1650s to 1890s) that showed painted glass slides on a screen."],"r":[]},{"t":"Master (parent) page","s":"C","m":["3"],"c":"M3","d":["A template page in layout software that holds repeating items such as page numbers, running heads and column guides."],"r":[]},{"t":"Match cut","s":"C","m":["3"],"c":"M3","d":["A cut between two shots that rhyme in shape, movement or subject, linking ideas across time or place."],"r":[]},{"t":"Match on action","s":"C","m":["3"],"c":"M3","d":["A cut made during a movement, continued in the next shot, so the edit is invisible."],"r":[]},{"t":"Measure","s":"C","m":["3"],"c":"M3","d":["The length of a line of text; about 45 to 75 characters is comfortable for body text."],"r":[]},{"t":"Media convergence","s":"C","m":["2"],"c":"M2","d":["The merging of previously separate media (print, radio, television, telephone, computing) onto shared digital devices and networks."],"r":[]},{"t":"Merchandising","s":"C","m":["2"],"c":"M2","d":["Selling branded products, such as T-shirts or stickers, based on a creator's content or characters."],"r":[]},{"t":"Metadata","s":"G","m":["1"],"c":"M1","d":["Data that describes other data, such as author, date, size, location or keywords. Example: A photo's EXIF data showing camera model and date taken.","Data that describes other content (title, author, date, keywords), enabling search and organisation.","Data about data, such as a photo's date, camera settings, location, author and keywords."],"r":[]},{"t":"Micro work","s":"C","m":["2"],"c":"M2","d":["Very small online tasks, such as tagging images or transcribing short clips, completed for small payments, often through crowdsourcing platforms."],"r":[]},{"t":"Millennials","s":"C","m":["2"],"c":"M2","d":["People born roughly 1981 to 1996, who witnessed the rise of the internet and social media."],"r":[]},{"t":"Mind map","s":"C","m":["3"],"c":"M3","d":["A diagram that places a central idea in the middle and branches related ideas outwards, used to explore and organise concepts."],"r":[]},{"t":"Minimum viable product (MVP)","s":"C","m":["2"],"c":"M2","d":["The simplest working version of a product that can be released to test whether it meets users' needs."],"r":[]},{"t":"Mise-en-scène","s":"C","m":["3"],"c":"M3","d":["Everything placed in front of the camera: setting, props, costume, lighting and the staging of performers."],"r":[]},{"t":"Misinformation / disinformation","s":"C","m":["1"],"c":"M1","d":["Misinformation is false information shared without intent to deceive. Disinformation is false information created or spread deliberately to deceive."],"r":[]},{"t":"Mobile-first","s":"C","m":["2"],"c":"M2","d":["Designing content and services primarily for smartphones, then adapting them for larger screens."],"r":[]},{"t":"Mock-up","s":"C","m":["3"],"c":"M3","d":["A high-fidelity, static picture of a screen or product showing the real colours, typography, icons, images and spacing, used to refine the look and win approval before anything is built."],"r":[]},{"t":"Monetisation","s":"G","m":["2"],"c":"M2","d":["Generating revenue from digital content or platforms through advertising, subscriptions or licensing.","Turning content or an audience into income, for example through advertising, subscriptions or sales."],"r":[]},{"t":"Monospace","s":"C","m":["3"],"c":"M3","d":["A typeface in which every character has the same width, such as Courier and Consolas."],"r":[]},{"t":"Montage editing","s":"C","m":["3"],"c":"M3","d":["Joining shots for theme or emotion rather than continuity, so a new meaning comes from their collision."],"r":[]},{"t":"Mood board","s":"C","m":["3"],"c":"M3","d":["A collage of images, colours, fonts and textures that communicates the intended look and feel of a project."],"r":[]},{"t":"Motivated lighting","s":"C","m":["3"],"c":"M3","d":["Film lighting arranged to seem as if it comes from a believable source in the scene, such as a lamp, window or fire."],"r":[]},{"t":"MOV","s":"X","m":["3"],"c":"M3","d":["Apple QuickTime video container, common on iPhones and in editing workflows."],"r":[]},{"t":"MP3","s":"X","m":["3"],"c":"M3","d":["A lossy compressed audio format; small files suitable for podcasts, streaming and sharing."],"r":[]},{"t":"MP4 (H.264)","s":"X","m":["3"],"c":"M3","d":["A common video container and codec pair that gives good quality at small file sizes; plays almost everywhere."],"r":[]},{"t":"Multimedia","s":"G","m":["1"],"c":"M1","d":["The combination of two or more media types (text, graphics, audio, video, animation) in a single product or presentation. Example: An educational website with text, video and audio narration.","A combination of media types (text, audio, video, images and animation) within a single digital product.","Content that combines two or more media types, such as text, images, audio, video and animation, in one product."],"r":[]},{"t":"Narrowband / broadband","s":"C","m":["1"],"c":"M1","d":["Narrowband is a low-capacity connection, such as dial-up. Broadband is a high-capacity, always-on connection, such as fibre, cable or 4G/5G."],"r":[]},{"t":"Near-term inequality","s":"C","m":["1"],"c":"M1","d":["Labour-market disruption and fast-changing skill demands that leave some workers behind, especially those without access to retraining or digital literacy programmes."],"r":[]},{"t":"Network effect","s":"C","m":["2"],"c":"M2","d":["The situation in which a platform becomes more valuable to each user as more people use it."],"r":[]},{"t":"Network redundancy","s":"C","m":["1"],"c":"M1","d":["Having more than one route or link (for example a second submarine cable or satellite back-up) so service continues if one fails."],"r":[]},{"t":"New media","s":"G","m":["1"],"c":"M1","d":["Digital forms of communication that are interactive, online and often user-driven, as opposed to traditional media such as print, radio and broadcast TV. Examples: websites and apps, video games, virtual reality.","Media that are digital, networked and usually interactive, such as websites, social media, apps and streaming services, as opposed to traditional print and broadcast media."],"r":[]},{"t":"Non-destructive editing","s":"C","m":["3"],"c":"M3","d":["Editing that keeps the original file unchanged, for example by using layers, adjustment layers, masks or an editing timeline."],"r":[]},{"t":"Non-linear editing (NLE)","s":"C","m":["1"],"c":"M1","d":["Digital editing in which any clip can be placed, moved or changed at any point on a timeline without altering the original footage."],"r":[]},{"t":"Normalise (audio)","s":"X","m":["3"],"c":"M3","d":["To raise the loudness of a clip so its highest peak reaches a set level, e.g. −1 dB, without clipping."],"r":[]},{"t":"One-light photography","s":"C","m":["3"],"c":"M3","d":["A technique that uses a single light source to illuminate the subject, creating simple, striking images with strong contrast and shadows."],"r":[]},{"t":"Online portfolio","s":"C","m":["2"],"c":"M2","d":["A curated, current and accessible collection of your best work online; the primary professional credential in digital media."],"r":[]},{"t":"Open data / open access","s":"C","m":["1"],"c":"M1","d":["Open data is data that anyone can freely use and republish. Open access is research and scholarship available online free of charge."],"r":[]},{"t":"Open educational resources (OER)","s":"C","m":["1"],"c":"M1","d":["Teaching and learning materials that are free to use, adapt and share, usually under an open licence."],"r":[]},{"t":"Open Movement","s":"C","m":["1"],"c":"M1","d":["A philosophy that knowledge, software, data and creative works should be freely available to use, study, adapt and share."],"r":[]},{"t":"Open source","s":"G","m":["1"],"c":"M1","d":["Software with publicly available source code that anyone can view, modify and distribute freely.","Software whose source code is published under a licence that lets anyone use, study, modify and share it, for example Linux, GIMP and Audacity."],"r":[]},{"t":"Openness","s":"C","m":["1"],"c":"M1","d":["How reachable a source is. Open sources can be used, combined and gathered for your purposes; closed sources are blocked by cost, licence or policy."],"r":[]},{"t":"Openness to feedback","s":"C","m":["2"],"c":"M2","d":["Actively seeking critique and using it to improve, rather than reacting defensively."],"r":[]},{"t":"Outsourcing","s":"C","m":["2"],"c":"M2","d":["Contracting work out to another company or freelancer, sometimes in another country."],"r":[]},{"t":"Over-the-shoulder shot (OTS)","s":"C","m":["3"],"c":"M3","d":["A shot framed from behind one character's shoulder towards another, used to keep dialogue geography clear."],"r":[]},{"t":"Pan and tilt","s":"C","m":["3"],"c":"M3","d":["Camera movements on a fixed point: a pan turns left or right; a tilt pivots up or down."],"r":[]},{"t":"Paragraph style","s":"C","m":["3"],"c":"M3","d":["A saved set of text formatting applied to whole paragraphs; changing the style updates every instance."],"r":[]},{"t":"Parallax","s":"C","m":["3"],"c":"M3","d":["The shift between foreground and background when the camera physically moves; present in a dolly, absent in a zoom."],"r":[]},{"t":"Patent","s":"G","m":["1"],"c":"M1","d":["Legal protection granted for inventions, giving the creator exclusive rights to use and commercialise it.","A registered right that gives an inventor exclusive control over a new, inventive and useful invention for a limited time, usually 20 years."],"r":[]},{"t":"Payment system","s":"C","m":["2"],"c":"M2","d":["A digital payment gateway, subscription billing service or monetisation tool that enables commerce across the ecosystem."],"r":[]},{"t":"Persistence of vision","s":"C","m":["1"],"c":"M1","d":["The traditional name for the effect by which a rapid series of still images is perceived as continuous motion."],"r":[]},{"t":"Personalisation","s":"G","m":["1"],"c":"M1","d":["Customising digital content and experiences for individual users based on their data, preferences and behaviour.","Tailoring content, recommendations or adverts to an individual user, usually by analysing their data and behaviour."],"r":[]},{"t":"PEST analysis","s":"C","m":["2"],"c":"M2","d":["A framework for analysing the Political (policy), Economic, Social and Technological factors in an environment; adding Cultural factors gives a PESTC analysis."],"r":[]},{"t":"Phenakistoscope","s":"C","m":["1"],"c":"M1","d":["An 1832 spinning slotted disc of sequential drawings viewed in a mirror; the first true animation device."],"r":[]},{"t":"Pixel","s":"G","m":["3","1"],"c":"M3","d":["The smallest single point of colour in a digital image or on a screen. Example: A 1920 × 1080 image has about 2 million pixels.","The smallest unit of a digital image: a single point of colour that combines with others to form a complete picture."],"r":[]},{"t":"Placeholder content","s":"C","m":["3"],"c":"M3","d":["Temporary shapes or text, such as a crossed box for an image or lines for paragraphs, that hold the place of final content in a wireframe."],"r":[]},{"t":"Plagiarism","s":"G","m":["1"],"c":"M1","d":["Using another person's work without proper acknowledgement: a serious ethical and academic offence."],"r":[]},{"t":"Platform","s":"G","m":["2","1"],"c":"M2","d":["A digital environment for creating, sharing and consuming content, e.g. YouTube, Instagram, TikTok.","A digital service that connects creators, audiences and advertisers, such as a video-sharing site, a streaming service or an app store."],"r":[]},{"t":"Platform economy","s":"G","m":["2"],"c":"M2","d":["An economic model built around digital platforms that connect producers and consumers of goods and services."],"r":[]},{"t":"Platform monetisation","s":"C","m":["2"],"c":"M2","d":["Programmes through which a platform pays creators, for example ad revenue sharing, live-stream gifts, paid memberships or podcast ad insertion."],"r":[]},{"t":"PNG","s":"X","m":["3"],"c":"M3","d":["A lossless image format that supports transparency; good for logos, screenshots and graphics with sharp edges."],"r":[]},{"t":"Podcast","s":"G","m":["3"],"c":"M3","d":["A digital audio series distributed online, typically in episodic format, covering a wide range of topics."],"r":[]},{"t":"Point-of-view shot (POV)","s":"C","m":["3"],"c":"M3","d":["A shot that shows exactly what a character sees, placing the audience in their position."],"r":[]},{"t":"Post-production","s":"G","m":["3"],"c":"M3","d":["Editing, colour grading, sound design and finishing work completed after the main content is captured."],"r":[]},{"t":"ppi (pixels per inch)","s":"X","m":["3"],"c":"M3","d":["The density of pixels in a digital image; 300 ppi is typical for print and 72 ppi is a common screen convention."],"r":[]},{"t":"Pre-production","s":"G","m":["3"],"c":"M3","d":["The planning stage (scripting, storyboarding, scheduling and resource allocation) before filming begins.","The planning stage before recording or building begins: brief, research, script, storyboard, budget, schedule, crew, equipment, locations and permissions."],"r":[]},{"t":"Pre-sales","s":"C","m":["2"],"c":"M2","d":["Selling a product before it is finished, such as pre-orders for an album or game, to raise money for production."],"r":[]},{"t":"Producer","s":"C","m":["2"],"c":"M2","d":["A company or team that develops, packages and finances digital media products at scale, from streaming series to branded content campaigns; in the value chain, the stakeholder who creates or commissions original content."],"r":[]},{"t":"Product backlog","s":"C","m":["2"],"c":"M2","d":["The prioritised list of everything that might be done on a project, often written as user stories."],"r":[]},{"t":"Professional ethics","s":"C","m":["2"],"c":"M2","d":["Standards of integrity, respect for intellectual property and responsible content practice expected of digital media professionals."],"r":[]},{"t":"Project brief","s":"C","m":["3"],"c":"M3","d":["A short document that states a project's purpose, audience, message, format, deliverables, budget and deadline."],"r":[]},{"t":"Project proposal","s":"C","m":["2"],"c":"M2","d":["A formal document that sets out a problem, the proposed solution, objectives, plan of action, budget, benefits and evaluation, in order to win approval or funding."],"r":[]},{"t":"Project-based production","s":"C","m":["2"],"c":"M2","d":["Organising work around discrete projects, each with defined deliverables, timelines and budgets."],"r":[]},{"t":"Proprietary software","s":"C","m":["1"],"c":"M1","d":["Closed software whose source code is kept secret by its owner; users may not study, modify or redistribute it."],"r":[]},{"t":"Prosumer","s":"C","m":["1","2"],"c":"M1","d":["A person who both produces and consumes media, typical of the Web 2.0 user."],"r":[]},{"t":"Prototype","s":"C","m":["3"],"c":"M3","d":["A version of a product that people can try. In app and web design it is usually a clickable simulation of navigation and interactions used for testing before development; it can also be a rough paper prototype."],"r":[]},{"t":"Prototyping","s":"G","m":["3"],"c":"M3","d":["Creating early models or mock-ups of a digital product to test ideas before full development."],"r":[]},{"t":"Proxemics","s":"C","m":["3"],"c":"M3","d":["The study of how people use space; on screen, the distance between characters (intimate, personal, social, public) signals their relationship."],"r":[]},{"t":"Psychology of colour","s":"C","m":["3"],"c":"M3","d":["The study of how colours affect feelings and perceptions, for example blue suggesting trust and calm, red suggesting energy or urgency."],"r":[]},{"t":"Public domain","s":"C","m":["1"],"c":"M1","d":["Works not protected by copyright, because protection has expired or the creator gave it up. Anyone may use them freely."],"r":[]},{"t":"Pull quote","s":"C","m":["3"],"c":"M3","d":["An enlarged quotation from an article placed in the layout to attract readers."],"r":[]},{"t":"QR code","s":"G","m":["1"],"c":"M1","d":["A scannable matrix barcode that links to digital data: websites, videos or contact information."],"r":[]},{"t":"Radial gradient","s":"C","m":["3"],"c":"M3","d":["A gradient that spreads outwards from a centre point in a circle or ellipse."],"r":[]},{"t":"Raster graphics","s":"G","m":["3","1"],"c":"M3","d":["Graphics made of a grid of pixels (bitmap), which lose quality when enlarged. Best for photographs. Examples: JPEG, PNG.","Pixel-based images, such as JPEGs and PNGs, that lose quality when scaled up beyond their original resolution."],"r":[]},{"t":"Raster graphics / pixel","s":"C","m":["1"],"c":"M1","d":["Raster images are made of a grid of pixels (the smallest points of colour), such as photographs. They lose quality when enlarged."],"r":[]},{"t":"Raster image","s":"C","m":["3"],"c":"M3","d":["An image made of a grid of pixels (e.g. a photograph). It loses quality when enlarged too far."],"r":[]},{"t":"RAW image","s":"X","m":["3"],"c":"M3","d":["The unprocessed data straight from a camera sensor, giving the most editing latitude but very large files."],"r":[]},{"t":"Read-only web (Web 1.0)","s":"C","m":["1"],"c":"M1","d":["The first stage of the web: static pages with no user interaction or content creation. Users were readers."],"r":[]},{"t":"Reflected gradient","s":"C","m":["3"],"c":"M3","d":["A linear gradient that mirrors back to its starting colour, used for ribbons and glossy or metallic effects."],"r":[]},{"t":"Regulator","s":"C","m":["2"],"c":"M2","d":["A body that sets and enforces rules for the media or telecommunications sector, such as licensing, consumer protection or data protection."],"r":[]},{"t":"Reintermediation","s":"C","m":["2"],"c":"M2","d":["The appearance of new digital middlemen, such as streaming platforms and app stores, after old intermediaries have been removed."],"r":[]},{"t":"Release form","s":"C","m":["3"],"c":"M3","d":["A signed document giving permission to record and publish a person (talent or model release) or a property (location release). A minor's release is signed by a parent or guardian."],"r":[]},{"t":"Rembrandt lighting","s":"C","m":["3"],"c":"M3","d":["Light at about 45° to the subject's face, slightly above eye level, leaving a small triangle of light on the shadowed cheek; moody and three-dimensional."],"r":[]},{"t":"Remote work","s":"G","m":["2"],"c":"M2","d":["Working outside a traditional office environment using digital tools and cloud-based collaboration platforms.","Working from home or anywhere with internet access, using cloud tools to collaborate with colleagues and clients."],"r":[]},{"t":"Rendering","s":"G","m":["3"],"c":"M3","d":["The process of producing the final output of a media file: converting raw data into a viewable image, video or animation."],"r":[]},{"t":"Resilience","s":"C","m":["2"],"c":"M2","d":["The ability to recover from setbacks, adapt to failure and persist towards goals."],"r":[]},{"t":"Resolution","s":"G","m":["3","1"],"c":"M3","d":["The amount of detail an image or display holds, given as pixel dimensions or pixels per inch (ppi/dpi). Examples: 1920 × 1080 (Full HD), 300 dpi for print.","The level of detail in a digital image or video, measured in pixels; higher resolution means greater clarity and larger file sizes.","The amount of detail in an image or video, given as pixel dimensions (e.g. 1920 x 1080). For print, it is described as pixels or dots per inch (PPI/DPI)."],"r":[]},{"t":"Resolution / aspect ratio","s":"C","m":["1"],"c":"M1","d":["Resolution is the amount of detail in an image or display (1920 by 1080 pixels, or 300 ppi). Aspect ratio is the proportion of width to height, such as 16:9, 1:1 or 9:16."],"r":[]},{"t":"Responsive design","s":"G","m":["3"],"c":"M3","d":["A web design approach that adapts layout and content to fit different screen sizes and devices automatically."],"r":[]},{"t":"Revenue-sharing model","s":"C","m":["2"],"c":"M2","d":["An arrangement in which a partner funds or distributes a project in return for a percentage of its future income."],"r":[]},{"t":"Rim light","s":"C","m":["3"],"c":"M3","d":["A bright outline of light around the edges of the subject (hair, shoulders) created by light from behind."],"r":[]},{"t":"Risk appetite","s":"C","m":["2"],"c":"M2","d":["The willingness to take calculated risks, an essential entrepreneurial skill for creative innovation."],"r":[]},{"t":"River","s":"C","m":["3"],"c":"M3","d":["A channel of white space running through justified text, caused by uneven word spacing."],"r":[]},{"t":"Royalty-free vs rights-managed","s":"C","m":["1"],"c":"M1","d":["Royalty-free content is licensed for a one-time fee (or free) and can be reused within the licence terms. Rights-managed content is licensed for one specific use, time, place or audience, and costs more for wider use."],"r":[]},{"t":"RSS (Really Simple Syndication)","s":"C","m":["1"],"c":"M1","d":["A feed that lets podcast apps and readers pick up new episodes or posts automatically."],"r":[]},{"t":"Rule of thirds","s":"C","m":["3"],"c":"M3","d":["A composition guideline that divides the frame with two horizontal and two vertical lines and places key subjects on the lines or where they cross."],"r":[]},{"t":"RYB colour model","s":"C","m":["3"],"c":"M3","d":["The traditional artist’s colour model with red, yellow and blue primaries, used for mixing paint and for the classic colour wheel."],"r":[]},{"t":"Sample rate","s":"C","m":["3"],"c":"M3","d":["How many times per second an audio signal is measured when it is digitised: 44.1 kHz for music and CD, 48 kHz for video."],"r":[]},{"t":"School-Based Assessment (SBA)","s":"X","m":["2"],"c":"M2","d":["The coursework part of the CAPE Digital Media examination (Paper 031), worth 60%: a product or service with a proposal, evidence of progress and process, and a 5-minute pitch, marked out of 45."],"r":[]},{"t":"Screen reader","s":"C","m":["1"],"c":"M1","d":["Software that reads on-screen text and image descriptions aloud, or outputs them to Braille, for blind and partially sighted users."],"r":[]},{"t":"Scrollytelling","s":"C","m":["1"],"c":"M1","d":["An online format in which charts and graphics change as the reader scrolls through a story."],"r":[]},{"t":"Search Engine Optimisation (SEO)","s":"G","m":["1"],"c":"M1","d":["Techniques used to improve a website's visibility and ranking in search engine results pages.","Improving content and websites so that they appear higher in search engine results."],"r":[]},{"t":"Selection","s":"C","m":["3"],"c":"M3","d":["Choosing the most suitable idea from those generated, using criteria such as purpose, audience, budget and feasibility."],"r":[]},{"t":"Semantic web (Web 3.0)","s":"C","m":["1"],"c":"M1","d":["The AI-based web of personalised, intelligent and machine-readable content; it is also linked with decentralisation."],"r":[]},{"t":"Serif","s":"C","m":["3"],"c":"M3","d":["A small finishing stroke at the end of a letter's main stroke; typefaces with them are serif faces, those without are sans serif."],"r":[]},{"t":"Sextortion","s":"C","m":["1"],"c":"M1","d":["Digital blackmail: threatening to share intimate images or personal information unless the victim pays or complies. Victims should not pay, should save evidence, report it and tell a trusted adult."],"r":[]},{"t":"Short-form vertical video","s":"C","m":["2"],"c":"M2","d":["Short clips, usually under a minute, filmed in portrait format for phone screens, popularised by TikTok and Instagram Reels."],"r":[]},{"t":"Shot list","s":"C","m":["3"],"c":"M3","d":["A numbered list of every shot needed, with shot type, angle, movement, location and notes, used on the day of filming."],"r":[]},{"t":"Shot size","s":"C","m":["3"],"c":"M3","d":["How much of the subject the frame shows, from extreme long shot (ELS) through long, medium, medium close-up and close-up to extreme close-up (ECU)."],"r":[]},{"t":"Simultaneous contrast","s":"C","m":["3"],"c":"M3","d":["The effect where colours placed side by side change how each other look; complementary colours next to each other appear more intense."],"r":[]},{"t":"Slab serif","s":"C","m":["3"],"c":"M3","d":["A serif style with heavy, block-like serifs and even stroke weight, such as Rockwell."],"r":[]},{"t":"Social media","s":"G","m":["1"],"c":"M1","d":["Online platforms and apps where users create profiles, share content and communicate or interact with others. Examples: Instagram, TikTok, Facebook, X (formerly Twitter).","Digital platforms for creating, sharing and engaging with content, e.g. Instagram, X, LinkedIn, TikTok."],"r":[]},{"t":"Social web (Web 2.0)","s":"C","m":["1"],"c":"M1","d":["The interactive, read-write web of social media, user-generated content and two-way communication. Users became participants."],"r":[]},{"t":"Source code","s":"C","m":["1"],"c":"M1","d":["The human-readable instructions programmers write. Open-source software makes it available to read, modify and share; proprietary software keeps it secret."],"r":[]},{"t":"Split lighting","s":"C","m":["3"],"c":"M3","d":["Light at 90° to the side, dividing the face into two equal halves, one lit and one in shadow; high-contrast and dramatic."],"r":[]},{"t":"Split-complementary harmony","s":"C","m":["3"],"c":"M3","d":["A colour scheme of a key colour plus the two colours either side of its complement, e.g. blue with yellow-orange and red-orange."],"r":[]},{"t":"Sponsorship","s":"C","m":["2"],"c":"M2","d":["Funding in cash or kind from a business in return for visibility, such as its logo or name in a production."],"r":[]},{"t":"Spread","s":"C","m":["3"],"c":"M3","d":["Two facing pages designed and seen together, as in a magazine or book."],"r":[]},{"t":"Sprint","s":"G","m":["2"],"c":"M2","d":["A short, time-boxed cycle within Agile project management, typically 1 to 4 weeks, focused on delivering a specific output.","A short, fixed period (often one to four weeks) in which an agile team creates and completes a set amount of work."],"r":[]},{"t":"Sprint backlog","s":"C","m":["2"],"c":"M2","d":["The list of tasks a team commits to completing during one sprint."],"r":[]},{"t":"Square colour harmony","s":"C","m":["3"],"c":"M3","d":["A four-colour scheme of hues evenly spaced around the colour wheel, e.g. red, yellow-orange, green and blue-violet."],"r":[]},{"t":"Stakeholder","s":"C","m":["2"],"c":"M2","d":["Any person or organisation with an interest in, or affected by, a project or value chain, such as producers, platforms, advertisers, funders and end users."],"r":[]},{"t":"Stakeholder buy-in","s":"C","m":["3"],"c":"M3","d":["Agreement and support for a design from the people with an interest in it, such as the client, managers or investors, often won with realistic mock-ups and prototypes."],"r":[]},{"t":"Stand-up","s":"C","m":["2"],"c":"M2","d":["A short daily team check-in, held during a sprint, in which each member says what they did, what they will do next and what is blocking them."],"r":[]},{"t":"Storyboard","s":"C","m":["3"],"c":"M3","d":["A sequence of drawn or photographed frames, with notes on shots, action, dialogue, audio and timing, that plans a video or animation shot by shot."],"r":[]},{"t":"Storyboarding","s":"G","m":["3"],"c":"M3","d":["Visual planning of a media production using sequential sketches or panels to map out scenes and narrative flow."],"r":[]},{"t":"Streaming","s":"G","m":["1"],"c":"M1","d":["Real-time delivery of audio or video content over the internet without requiring full download first."],"r":[]},{"t":"Streaming Media","s":"G","m":["1"],"c":"M1","d":["Audio or video content delivered continuously over the internet and played as it arrives, without needing to download the whole file first. Examples: Netflix, YouTube, Spotify."],"r":[]},{"t":"Streaming vs download media","s":"C","m":["1"],"c":"M1","d":["Streaming plays audio or video while it is still arriving, without the user keeping a full copy. Download media are copied in full to the device so they can be used offline."],"r":[]},{"t":"Structured data","s":"C","m":["1"],"c":"M1","d":["Information tagged in a standard, machine-readable way (for example schema markup) so search engines and AI can understand what it means."],"r":[]},{"t":"Studio system","s":"C","m":["1"],"c":"M1","d":["The 1930s to 1940s Hollywood model in which major studios controlled production, distribution and exhibition (vertical integration), with stars under contract."],"r":[]},{"t":"Submarine cable","s":"C","m":["1"],"c":"M1","d":["A cable laid on the seabed that carries Internet traffic between islands and continents; most Caribbean international traffic travels this way."],"r":[]},{"t":"Subscription","s":"C","m":["2"],"c":"M2","d":["A regular payment, often monthly, for ongoing access to content or a service."],"r":[]},{"t":"Subscription video on demand (SVOD)","s":"C","m":["1"],"c":"M1","d":["Streaming services that give subscribers access to a library of films and series to watch at any time."],"r":[]},{"t":"Subtractive colour (CMYK)","s":"C","m":["3"],"c":"M3","d":["Colour made by inks that absorb (subtract) light, used in printing: cyan, magenta, yellow and key (black). More ink gives a darker result."],"r":[]},{"t":"SVG","s":"X","m":["3"],"c":"M3","d":["A vector graphics format that scales to any size without losing quality; used for logos and icons on the web."],"r":[]},{"t":"Symbiotic web (Web 4.0)","s":"C","m":["1"],"c":"M1","d":["An emerging stage of intelligent connected systems integrating IoT, AI and real-time data, in which humans and machines work as partners."],"r":[]},{"t":"Target audience","s":"G","m":["3"],"c":"M3","d":["The specific group of users or viewers a piece of digital content is designed and intended to reach."],"r":[]},{"t":"Technology adoption lifecycle","s":"C","m":["1"],"c":"M1","d":["A model showing how groups take up a new technology over time: innovators, early adopters, early majority, late majority and laggards."],"r":[]},{"t":"Telecommuting","s":"C","m":["2"],"c":"M2","d":["Working from home or another location away from the office, using digital tools to stay connected."],"r":[]},{"t":"Tetradic (rectangle) harmony","s":"C","m":["3"],"c":"M3","d":["A four-colour scheme made of two complementary pairs, e.g. orange and blue with yellow and violet; one colour should dominate."],"r":[]},{"t":"Thaumatrope","s":"C","m":["1"],"c":"M1","d":["An 1825 optical toy: a disc with a picture on each side that fuse into one image when spun."],"r":[]},{"t":"The 5 Rs of open content","s":"C","m":["1"],"c":"M1","d":["The permissions an open licence gives: retain, reuse, revise, remix and redistribute (David Wiley)."],"r":[]},{"t":"Three-act structure","s":"C","m":["3"],"c":"M3","d":["A story shape of setup (about 25%), confrontation (about 50%) and resolution (about 25%)."],"r":[]},{"t":"Three-point lighting","s":"C","m":["3"],"c":"M3","d":["A standard lighting set-up using a key light (main), a fill light (softens shadows) and a back light (separates the subject from the background)."],"r":[]},{"t":"Thumbnail sketch","s":"C","m":["3"],"c":"M3","d":["A tiny, quick drawing used to plan a shot or layout before making a detailed version."],"r":[]},{"t":"TIFF","s":"X","m":["3"],"c":"M3","d":["A high-quality, usually lossless image format used for printing, scanning and archiving."],"r":[]},{"t":"Tint and shade","s":"C","m":["3"],"c":"M3","d":["A tint is a hue lightened with white; a shade is a hue darkened with black."],"r":[]},{"t":"Tone (colour)","s":"C","m":["3"],"c":"M3","d":["A hue with grey added, which mutes it and lowers its saturation."],"r":[]},{"t":"Tracking","s":"C","m":["3"],"c":"M3","d":["Adjusting the spacing evenly across a whole word, line or block of text."],"r":[]},{"t":"Traction","s":"C","m":["2"],"c":"M2","d":["Evidence that an idea is working, such as early users, followers, sales, pre-orders or partnerships."],"r":[]},{"t":"Trademark","s":"G","m":["1"],"c":"M1","d":["A legally registered brand symbol, name or sign that distinguishes a company's products or services.","A sign such as a name, logo or slogan that identifies a business's goods or services and distinguishes them from others."],"r":[]},{"t":"Traditional Artwork","s":"G","m":["1"],"c":"M1","d":["Art created using physical materials such as paint, canvas, pencil or clay. It exists as a unique, tangible original that is difficult to change once finished and relies on manual, hand-crafted techniques. Example: An oil painting on canvas."],"r":[]},{"t":"Treemap","s":"C","m":["1"],"c":"M1","d":["A chart of nested rectangles whose areas show hierarchical parts of a whole."],"r":[]},{"t":"Trim and safe area","s":"C","m":["3"],"c":"M3","d":["The trim is the final cut size of a printed piece; the safe area is the zone inside it where text and logos are kept."],"r":[]},{"t":"Truncated axis","s":"C","m":["1"],"c":"M1","d":["A chart axis that does not start at zero, which can exaggerate differences."],"r":[]},{"t":"Typeface classification","s":"C","m":["3"],"c":"M3","d":["Grouping typefaces by history and form: serif (Old Style, Transitional, Didone, slab), sans serif (grotesque, neo-grotesque, geometric, humanist), script, display and monospace."],"r":[]},{"t":"UI (User Interface)","s":"G","m":["3"],"c":"M3","d":["The visual layout and interactive elements that users see and engage with on a digital product or platform."],"r":[]},{"t":"Unity","s":"C","m":["3"],"c":"M3","d":["The sense that all parts of a design belong together, created through consistent colour, type, spacing and style."],"r":[]},{"t":"URL (Uniform Resource Locator)","s":"G","m":["1"],"c":"M1","d":["A web address that specifies the location of a resource on the internet, e.g. https://www.example.com."],"r":[]},{"t":"Usability testing","s":"C","m":["3"],"c":"M3","d":["Watching real users try to complete tasks on a design or prototype to find where they get confused or stuck."],"r":[]},{"t":"User flow","s":"C","m":["3"],"c":"M3","d":["The path a user takes through screens to complete a task, such as landing screen, sign-up, account creation and first login."],"r":[]},{"t":"User persona","s":"C","m":["2"],"c":"M2","d":["A short, research-based profile of a typical user, with a name, age, goals, habits and frustrations, used to design for a real audience."],"r":[]},{"t":"User-centred design","s":"G","m":["3"],"c":"M3","d":["A design philosophy that places the needs, behaviours and goals of users at the heart of every decision.","Designing around the real needs, abilities and contexts of the people who will use the solution, and involving them throughout."],"r":[]},{"t":"User-generated content (UGC)","s":"G","m":["1","2"],"c":"M1","d":["Content such as posts, videos, reviews and photos created and published by ordinary users rather than by professional organisations. Examples: a TikTok video, a product review, a Wikipedia edit.","Content created and published by users rather than brands: reviews, videos, posts and comments.","Content created by ordinary users rather than professionals or brands, such as reviews, videos, comments and memes."],"r":[]},{"t":"UX (User Experience)","s":"G","m":["3"],"c":"M3","d":["The overall experience a person has when interacting with a digital product, encompassing usability, accessibility and satisfaction."],"r":[]},{"t":"Validation","s":"C","m":["3"],"c":"M3","d":["Checking, with real users and against the requirements, that a solution actually solves the problem it was designed for."],"r":[]},{"t":"Value chain","s":"G","m":["2"],"c":"M2","d":["The full process from content creation through to distribution and consumption; each stage adds value to the final product.","The sequence of activities that add value to a product, from creation to production, distribution, marketing and consumption."],"r":[]},{"t":"Vector graphics","s":"G","m":["1","3"],"c":"M1","d":["Graphics made of mathematical paths, points and curves, which scale to any size without quality loss. Best for logos and icons. Example: SVG.","Scalable images built using mathematical formulas rather than pixels; they retain quality at any size, ideal for logos and icons.","Images made of mathematical paths, points and shapes, such as logos. They can be resized without losing quality."],"r":[]},{"t":"Vector image","s":"C","m":["3"],"c":"M3","d":["An image made of mathematical paths and shapes (e.g. a logo in SVG or AI format). It can be scaled to any size without losing quality."],"r":[]},{"t":"Venture capitalist (VC)","s":"C","m":["2"],"c":"M2","d":["A professional firm that invests pooled funds in high-growth businesses in exchange for equity, expecting a large return."],"r":[]},{"t":"Visual hierarchy","s":"C","m":["3"],"c":"M3","d":["The order in which the eye reads a design, set by size, weight, colour, position, spacing and contrast; usually primary, secondary and tertiary levels."],"r":[]},{"t":"Visual motif","s":"C","m":["3"],"c":"M3","d":["An image, object or colour that recurs in a film and gathers meaning each time."],"r":[]},{"t":"Visual weight","s":"C","m":["3"],"c":"M3","d":["How strongly an element attracts the eye; increased by size, saturated or warm colour, isolation and complexity."],"r":[]},{"t":"VR (Virtual Reality)","s":"G","m":["1"],"c":"M1","d":["A fully immersive digital environment experienced through a headset, simulating a three-dimensional world."],"r":[]},{"t":"Waterfall","s":"C","m":["2"],"c":"M2","d":["A traditional, linear project management approach in which each stage is completed and signed off before the next begins."],"r":[]},{"t":"WAV","s":"X","m":["3"],"c":"M3","d":["An uncompressed audio format with full quality and large files; used for recording and editing."],"r":[]},{"t":"Web 1.0","s":"G","m":["1"],"c":"M1","d":["The read-only web: static pages with no user interaction or content creation."],"r":[]},{"t":"Web 1.0 to Web 5.0","s":"C","m":["1"],"c":"M1","d":["Stages in the web's development: Read-Only Web (1.0), Read-Write or Social Web (2.0), Semantic and Decentralised Web (3.0), Symbiotic Web (4.0) and Emotional or Unseen Web (5.0)."],"r":[]},{"t":"Web 2.0","s":"G","m":["1"],"c":"M1","d":["The interactive web: social media, user-generated content and two-way communication."],"r":[]},{"t":"Web 3.0","s":"G","m":["1"],"c":"M1","d":["The AI-based semantic web: personalised, intelligent and machine-readable content."],"r":[]},{"t":"Web 4.0","s":"G","m":["1"],"c":"M1","d":["Intelligent connected systems integrating IoT, AI and real-time data for seamless digital environments."],"r":[]},{"t":"Web 5.0","s":"G","m":["1"],"c":"M1","d":["The sensory and emotional web: systems that respond to human emotions and sensory input."],"r":[]},{"t":"Webcast / multicasting","s":"C","m":["1"],"c":"M1","d":["A webcast is a broadcast of live or recorded media over the Internet. Multicasting sends one stream to many receivers at once, saving bandwidth."],"r":[]},{"t":"White balance","s":"C","m":["3"],"c":"M3","d":["A camera setting that makes white objects appear white under different light sources, measured in kelvin (about 3200 K for indoor tungsten, about 5600 K for daylight)."],"r":[]},{"t":"Widow and orphan","s":"C","m":["3"],"c":"M3","d":["A widow is a short last line of a paragraph stranded at the top of a column; an orphan is a first line left alone at the bottom of a column."],"r":[]},{"t":"Wireframe","s":"G","m":["3"],"c":"M3","d":["A basic structural layout design used in the early stages of web or app development to map out content placement and user flow.","A simple layout sketch of a web page or app screen showing where content and controls go, without final colours or images."],"r":[]},{"t":"x-height","s":"C","m":["3"],"c":"M3","d":["The height of lowercase letters without ascenders or descenders, such as x; a large x-height improves legibility at small sizes."],"r":[]},{"t":"XML (Extensible Markup Language)","s":"G","m":["1"],"c":"M1","d":["A markup language used for storing and transporting structured data in a human- and machine-readable format."],"r":[]},{"t":"XR (Extended Reality)","s":"G","m":["1"],"c":"M1","d":["An umbrella term for all immersive technologies: Augmented Reality (AR), Virtual Reality (VR) and Mixed Reality (MR)."],"r":[]},{"t":"Z-pattern and F-pattern","s":"C","m":["3"],"c":"M3","d":["Common eye paths: a Z across simple pages and posters; an F down text-heavy pages."],"r":[]},{"t":"Zoetrope","s":"C","m":["1"],"c":"M1","d":["An 1834 spinning drum with slits through which a looping strip of sequential images appears to move."],"r":[]}]};
